#!/usr/bin/env bash
set -euo pipefail

# Extracts public Firebase Web & Android client keys from app/lib/firebase_options.dart
# (generated by `make configure-firebase`) and writes them cleanly into infra/.env.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
ENV_FILE="${SCRIPT_DIR}/.env"
TEMPLATE_FILE="${SCRIPT_DIR}/.env.template"
OPTIONS_FILE="${ROOT_DIR}/app/lib/firebase_options.dart"

if [[ ! -f "${OPTIONS_FILE}" ]]; then
  echo "Error: ${OPTIONS_FILE} not found. Run 'make configure-firebase' first."
  exit 1
fi

if ! grep -q "static const FirebaseOptions" "${OPTIONS_FILE}"; then
  echo "Note: ${OPTIONS_FILE} is still the default --dart-define template (not flutterfire-generated)."
  echo "      Run 'make configure-firebase' to generate platform keys, or set FIREBASE_* manually in infra/.env."
  exit 0
fi

if [[ ! -f "${ENV_FILE}" ]]; then
  echo "==> Creating ${ENV_FILE} from ${TEMPLATE_FILE}..."
  cp "${TEMPLATE_FILE}" "${ENV_FILE}"
fi

extract_field() {
  local platform="$1"
  local field="$2"
  awk -v plat="static const FirebaseOptions ${platform} = FirebaseOptions(" -v key="${field}:" '
    index($0, plat) > 0 { in_block=1; next }
    in_block && /\);/ { in_block=0 }
    in_block && index($0, key) > 0 {
      if (match($0, /\x27[^\x27]*\x27/)) {
        val = substr($0, RSTART+1, RLENGTH-2)
        print val
        exit
      }
    }
  ' "${OPTIONS_FILE}"
}

upsert_env() {
  local key="$1"
  local val="$2"
  [[ -z "${val}" ]] && return 0
  if grep -q "^${key}=" "${ENV_FILE}"; then
    # Use python/awk-free portable temp-file rewrite to avoid sed delimiter issues
    awk -v k="${key}" -v v="${val}" '
      index($0, k "=") == 1 { print k "=" v; next }
      { print }
    ' "${ENV_FILE}" > "${ENV_FILE}.tmp" && mv "${ENV_FILE}.tmp" "${ENV_FILE}"
  else
    printf "\n%s=%s\n" "${key}" "${val}" >> "${ENV_FILE}"
  fi
}

WEB_API_KEY="$(extract_field web apiKey)"
WEB_APP_ID="$(extract_field web appId)"
WEB_SENDER_ID="$(extract_field web messagingSenderId)"
ANDROID_API_KEY="$(extract_field android apiKey)"
ANDROID_APP_ID="$(extract_field android appId)"
ANDROID_SENDER_ID="$(extract_field android messagingSenderId)"
PROJECT_ID="$(extract_field web projectId)"
if [[ -z "${PROJECT_ID}" ]]; then
  PROJECT_ID="$(extract_field android projectId)"
fi
SENDER_ID="${WEB_SENDER_ID:-${ANDROID_SENDER_ID}}"

echo "==> Syncing Firebase client keys from app/lib/firebase_options.dart into infra/.env..."
[[ -n "${PROJECT_ID}" ]] && upsert_env "GOOGLE_CLOUD_PROJECT" "${PROJECT_ID}"
[[ -n "${WEB_API_KEY}" ]] && upsert_env "FIREBASE_API_KEY" "${WEB_API_KEY}"
[[ -n "${WEB_APP_ID}" ]] && upsert_env "FIREBASE_APP_ID" "${WEB_APP_ID}"
[[ -n "${ANDROID_API_KEY}" ]] && upsert_env "FIREBASE_ANDROID_API_KEY" "${ANDROID_API_KEY}"
[[ -n "${ANDROID_APP_ID}" ]] && upsert_env "FIREBASE_ANDROID_APP_ID" "${ANDROID_APP_ID}"
[[ -n "${SENDER_ID}" ]] && upsert_env "FIREBASE_MESSAGING_SENDER_ID" "${SENDER_ID}"

echo "✓ Updated infra/.env:"
echo "  GOOGLE_CLOUD_PROJECT=${PROJECT_ID:-<unchanged>}"
echo "  FIREBASE_API_KEY=$([[ -n "${WEB_API_KEY}" ]] && echo "<set>" || echo "<missing>")"
echo "  FIREBASE_APP_ID=$([[ -n "${WEB_APP_ID}" ]] && echo "<set>" || echo "<missing>")"
echo "  FIREBASE_ANDROID_API_KEY=$([[ -n "${ANDROID_API_KEY}" ]] && echo "<set>" || echo "<missing>")"
echo "  FIREBASE_ANDROID_APP_ID=$([[ -n "${ANDROID_APP_ID}" ]] && echo "<set>" || echo "<missing>")"
echo "  FIREBASE_MESSAGING_SENDER_ID=$([[ -n "${SENDER_ID}" ]] && echo "<set>" || echo "<missing>")"
